using System.Drawing;
using System.Windows.Forms;
using System.Windows.Forms.VisualStyles;
namespace ZenForms.Core { public class ZenMenuRenderer:ToolStripProfessionalRenderer { public ZenMenuRenderer():base(new ZenColorTable()){} protected override void OnRenderToolStripBackground(ToolStripRenderEventArgs e){using(SolidBrush b=new SolidBrush(ZenTheme.Surface))e.Graphics.FillRectangle(b,e.AffectedBounds);} protected override void OnRenderMenuItemBackground(ToolStripItemRenderEventArgs e){Rectangle r=new Rectangle(Point.Empty,e.Item.Size);Color c=e.Item.Selected?ZenTheme.SurfaceRaised:ZenTheme.Surface;using(SolidBrush b=new SolidBrush(c))e.Graphics.FillRectangle(b,r);} protected override void OnRenderSeparator(ToolStripSeparatorRenderEventArgs e){int y=e.Item.ContentRectangle.Top+e.Item.ContentRectangle.Height/2;using(Pen p=new Pen(ZenTheme.Border))e.Graphics.DrawLine(p,e.Item.ContentRectangle.Left+8,y,e.Item.ContentRectangle.Right-8,y);} } internal class ZenColorTable:ProfessionalColorTable { public override Color MenuStripGradientBegin{get{return ZenTheme.Surface;}} public override Color MenuStripGradientEnd{get{return ZenTheme.Surface;}} public override Color ToolStripDropDownBackground{get{return ZenTheme.Surface;}} public override Color ImageMarginGradientBegin{get{return ZenTheme.Surface;}} public override Color ImageMarginGradientMiddle{get{return ZenTheme.Surface;}} public override Color ImageMarginGradientEnd{get{return ZenTheme.Surface;}} public override Color MenuItemSelected{get{return ZenTheme.SurfaceRaised;}} public override Color MenuItemSelectedGradientBegin{get{return ZenTheme.SurfaceRaised;}} public override Color MenuItemSelectedGradientEnd{get{return ZenTheme.SurfaceRaised;}} public override Color MenuBorder{get{return ZenTheme.Border;}} public override Color SeparatorDark{get{return ZenTheme.Border;}} } }

